def final_positions(nums, moveFrom, moveTo):
    # Create a set to store the occupied positions
    occupied_positions = set(nums)

    # Create a set to store the final positions
    final_positions = set()

    # Iterate through the moveFrom and moveTo arrays
    for i in range(len(moveFrom)):
        # Move all marbles from moveFrom[i] to moveTo[i]
