def matrix_mult(A, B, mod):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
    return result

def matrix_pow(matrix, power, mod):
    n = len(matrix)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]  # Identity matrix
    base = matrix
    while power:
        if power % 2 == 1:
            result = matrix_mult(result, base, mod)
        base = matrix_mult(base, base, mod)
        power //= 2
    return result

def string_transformation(s, t, k):
    n = len(s)
    if s == t:
        return 1 if k == 0 else 0

    # Create the transition matrix
    transition_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                transition_matrix[i][j] = 1

    # Raise the transition matrix to the power of k
    transition_matrix_k = matrix_pow(transition_matrix, k, MOD)

    # The result is the number of ways to reach the target string t from the initial string s
    return transition_matrix_k[0][n-1]

