                        else:
                            dp[i + 1][j][k] = (dp[i + 1][j][k] + dp[i][j][k]) % MOD
                        dp[i + 1][j][k] = (dp[i + 1][j][k] + dp[i][j][k]) % MOD
                else:
                    if j == 0:
                        dp[i + 1][1][k] = (dp[i + 1][1][k] + dp[i][0][k]) % MOD
                    else:
                        dp[i + 1][j][k] = (dp[i + 1][j][k] + dp[i][j][k]) % MOD

    # Sum up all valid states at the end of the string
    result = 0
