def is_infected(N, D, points):
    infected = [False] * N
    infected[0] = True

    for i in range(1, N):
        for j in range(i):
            if math.sqrt((points[i][0] - points[j][0])**2 + (points[i][1] - points[j][1])**2) <= D:
                infected[i] = True
                infected[j] = True

    return ["Yes" if i else "No" for i in infected]

