    # Paste sheets A and B onto the combined grid
    for i in range(H_A):
        for j in range(W_A):
            combined_grid[i + H_B][j + W_B] = A[i][j]
    for i in range(H_B):
        for j in range(W_B):
            combined_grid[i + H_A][j + W_B] = B[i][j]

