def min_operations(N, A):
    min_val = min(A)
    max_val = max(A)

    if max_val - min_val <= 1:
        return 0

    operations = 0

    for i in range(N):
        if A[i] < min_val:
            operations += (min_val - A[i])
        elif A[i] > max_val:
            operations += (A[i] - max_val)

    return operations

