    energy = {start: 0}
    queue = deque([start])

    # Process medicines
    for r, c, e in medicines:
        energy[r, c] = e
        queue.append((r, c))

    # BFS
    while queue:
        x, y = queue.popleft()

        # Check if we reached the goal
        if (x, y) == goal:
            return "Yes"

        # Explore neighbors
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and energy[nx, ny] > 0:
                energy[nx, ny] -= 1
                queue.append((nx, ny))

    return "No"

