def max_happiness(happiness, k):
    n = len(happiness)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + happiness[i - 1])

    return dp[n][k]

def shortest_substring(arr):
    answer = []
    for i in range(len(arr)):
        substrings = set()
        for j in range(len(arr[i])):
            for k in range(j, len(arr[i])):
                substrings.add(arr[i][j:k+1])
        if substrings:
