def sum_of_powers(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * n for _ in range(k)]

    for i in range(k):
        dp[i][0] = 0

    for i in range(1, n):
        for j in range(1, k):
            dp[j][i] = min(dp[j-1][i], dp[j][i-1])
            dp[j][i] += abs(nums[i] - nums[i-j])
            dp[j][i] %= MOD

    return sum(dp[k-1]) % MOD

def minCost(nums, cost1, cost2):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + cost1
        for j in range(i - 1, -1, -1):
            dp[i] = min(dp[i], dp[j] + cost2)
    return dp[n] % MOD

